<?php

declare(strict_types=1);

namespace Tests\Unit;

use PHPUnit\Framework\TestCase;
use Scroll;

/**
 * assets/scrolls/free-space.json is only a promise to the typeset engine while it covers
 * every certificate a person can print.
 *
 * The file is generated by tools/scroll-sweep/profile.spec.ts from the same vocabulary the
 * sweep reads (tools/scroll-sweep/axes.json), so this test fails in exactly two ways: a
 * design, ground, border, numeral set or rank was added and the profiles were not rebuilt,
 * or the builder wrote an entry that means nothing. Both are fixed by one command:
 *
 *     npm run profile:scrolls
 *
 * A missing entry is not silent at run time: Scroll::FreeSpace() returns null for it and
 * the engine then treats the certificate as unconstrained, which is exactly how a new
 * archer printed across a name. That is why a gap is a failure here and not a fallback.
 *
 * Modelled on ScrollSweepCoverageTest. Rank 0 is covered for the numeral sets too, and the
 * entry is a real measurement: custom.tpl draws no numeral at rank 0, so the render the
 * builder takes for rankset/<set>/0 has nothing of the set's in it and the entry is the
 * full frame in every band. It is written rather than omitted so that "every set at every
 * rank" stays one rule, and so a lookup never has to know which rank is the exception.
 */
final class ScrollFreeSpaceCoverageTest extends TestCase
{
    private const AXES = __DIR__ . '/../../tools/scroll-sweep/axes.json';
    private const REGENERATE = 'Run: npm run profile:scrolls';

    /** The frame the free interval is measured in: the certificate's own 2550x3300 foreignObject. */
    private const FRAME_WIDTH = 2550;

    /** @var array<string, mixed>|null */
    private ?array $manifest = null;

    /** @return array<string, mixed> */
    private function axes(): array
    {
        $this->assertFileExists(self::AXES, 'Run: php tools/scroll-sweep/bin/dump-axes.php > tools/scroll-sweep/axes.json');

        return json_decode((string) file_get_contents(self::AXES), true, 512, JSON_THROW_ON_ERROR);
    }

    /** @return array<string, mixed> */
    private function manifest(): array
    {
        if ($this->manifest !== null) {
            return $this->manifest;
        }

        $path = DIR_ASSETS . 'scrolls/free-space.json';
        $this->assertFileExists($path, self::REGENERATE);
        $decoded = json_decode((string) file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);
        $this->assertIsArray($decoded);
        $this->assertIsArray($decoded['configs'] ?? null, 'free-space.json has no "configs" map. ' . self::REGENERATE);
        $this->assertIsArray($decoded['components'] ?? null, 'free-space.json has no "components" map. ' . self::REGENERATE);

        return $this->manifest = $decoded;
    }

    /**
     * Every key a fixed order must have: order/variant/rank for each variant and each rank
     * the order draws. warrior starts at 1 (Scroll::Orders() says so), which is why this is
     * read from the orders and not from axes.json's blanket 0-10.
     *
     * @return list<string>
     */
    private function expectedConfigKeys(): array
    {
        $orders = Scroll::Orders();
        $keys   = [];
        foreach ($this->axes()['orderVariants'] as $ov) {
            if ($ov['order'] === 'custom') {
                continue;
            }
            $this->assertArrayHasKey($ov['order'], $orders, "{$ov['order']} is in axes.json but is not an order");
            $ranks = $orders[$ov['order']]['ranks'];
            for ($rank = (int) $ranks['from']; $rank <= (int) $ranks['to']; $rank++) {
                $keys[] = $ov['order'] . '/' . $ov['variant'] . '/' . $rank;
            }
        }

        return $keys;
    }

    /**
     * Every component a custom scroll is composed from. "none" is not a border to measure,
     * so it has no entry; Scroll::FreeSpace() skips an absent component for the same reason.
     *
     * @return list<string>
     */
    private function expectedComponentKeys(): array
    {
        $axes = $this->axes();
        $keys = [];
        foreach ($axes['grounds'] as $ground) {
            $keys[] = 'ground/' . $ground;
        }
        foreach ($axes['borders'] as $border) {
            if ($border !== 'none') {
                $keys[] = 'border/' . $border;
            }
        }
        foreach ($axes['rankSets'] as $set) {
            foreach ($axes['ranks'] as $rank) {
                $keys[] = 'rankset/' . $set . '/' . $rank;
            }
        }

        return $keys;
    }

    public function testTheHeaderRecordsTheGridAndTheMeasuredThresholds(): void
    {
        $m = $this->manifest();

        $this->assertSame(1, $m['v']);
        $this->assertSame(400, $m['y0']);
        $this->assertSame(25, $m['step']);
        $this->assertSame(80, $m['bands']);
        $this->assertSame(self::FRAME_WIDTH, $m['frameWidth']);
        foreach (['clearance', 'centerExclusion', 'inkThreshold', 'groundDark', 'groundLight', 'ownBorderDistance', 'groundBlur'] as $key) {
            $this->assertArrayHasKey($key, $m, "the header does not record $key. " . self::REGENERATE);
            $this->assertIsNumeric($m[$key], $key);
            $this->assertGreaterThan(0, $m[$key], $key);
        }
        $this->assertLessThan(1, $m['inkThreshold']);
        $this->assertLessThan(1, $m['groundLight']);
        $this->assertGreaterThan($m['groundDark'], $m['groundLight'], 'the dark and light ground cut-offs cross');
    }

    public function testTheProfilesWereBuiltFromTheCurrentUnderlayPolicy(): void
    {
        // The policy is a draft until the owner signs the review sheet, and every plate it moves
        // between "underlay" and "obstacle" moves the profile of every certificate that draws it.
        // The manifest carries the hash of the policy it was built from, so an edit to the policy
        // that is not followed by a rebuild fails here instead of shipping profiles for a design
        // nobody has signed.
        $m = $this->manifest();

        $this->assertSame(
            sha1_file(DIR_ORK3 . 'data/scroll-layout-underlays.php'),
            $m['underlayPolicySha1'] ?? null,
            'free-space.json was built from a different underlay policy than the one on disk. ' . self::REGENERATE
        );
    }

    public function testEveryFixedOrderVariantAndRankHasAProfile(): void
    {
        $configs = $this->manifest()['configs'];
        $missing = array_values(array_diff($this->expectedConfigKeys(), array_keys($configs)));

        $this->assertSame(
            [],
            $missing,
            'No free-space profile for: ' . implode(', ', array_slice($missing, 0, 12))
            . (count($missing) > 12 ? ' (+' . (count($missing) - 12) . ' more)' : '') . '. ' . self::REGENERATE
        );
    }

    public function testHunterIsCovered(): void
    {
        // hunter is not an ORK award id (the fixture renderer reaches it by name), so a builder
        // that walked the award catalogue would skip it. It has to be here at every rank.
        $configs = $this->manifest()['configs'];
        foreach (range(0, 10) as $rank) {
            $this->assertArrayHasKey('hunter//' . $rank, $configs, "hunter rank $rank has no profile. " . self::REGENERATE);
        }
    }

    public function testEveryGroundBorderAndNumeralSetHasAComponent(): void
    {
        $components = $this->manifest()['components'];
        $missing    = array_values(array_diff($this->expectedComponentKeys(), array_keys($components)));

        $this->assertSame(
            [],
            $missing,
            'No free-space component for: ' . implode(', ', array_slice($missing, 0, 12))
            . (count($missing) > 12 ? ' (+' . (count($missing) - 12) . ' more)' : '') . '. ' . self::REGENERATE
        );
    }

    public function testNoEntryNamesSomethingTheVocabularyDoesNot(): void
    {
        // A stale entry for a retired ground or a renamed order is harmless to the lookup and
        // misleading to read. The builder rewrites the whole file, so a leftover is a bug.
        $m = $this->manifest();

        $this->assertSame([], array_values(array_diff(array_keys($m['configs']), $this->expectedConfigKeys())), 'stale configs. ' . self::REGENERATE);
        $this->assertSame([], array_values(array_diff(array_keys($m['components']), $this->expectedComponentKeys())), 'stale components. ' . self::REGENERATE);
    }

    public function testEveryEntryHasOneEdgePerBandAndTheEdgesDoNotCross(): void
    {
        $m     = $this->manifest();
        $bands = $m['bands'];
        $seen  = 0;

        foreach (['configs', 'components'] as $group) {
            foreach ($m[$group] as $key => $entry) {
                $this->assertIsArray($entry['L'] ?? null, "$group/$key has no L");
                $this->assertIsArray($entry['R'] ?? null, "$group/$key has no R");
                $this->assertCount($bands, $entry['L'], "$group/$key: L is not $bands bands");
                $this->assertCount($bands, $entry['R'], "$group/$key: R is not $bands bands");
                for ($i = 0; $i < $bands; $i++) {
                    $l = $entry['L'][$i];
                    $r = $entry['R'][$i];
                    $this->assertIsInt($l, "$group/$key L[$i]");
                    $this->assertIsInt($r, "$group/$key R[$i]");
                    $this->assertGreaterThanOrEqual(0, $l, "$group/$key L[$i] is left of the frame");
                    $this->assertLessThanOrEqual(self::FRAME_WIDTH, $r, "$group/$key R[$i] is right of the frame");
                    $this->assertLessThan($r, $l, "$group/$key band $i: L=$l is not left of R=$r");
                }
                $seen++;
            }
        }

        $this->assertGreaterThan(0, $seen, 'no entries at all');
    }

    public function testTheLookupFindsAnEntryForEveryFixedOrderAndEveryCustomComponent(): void
    {
        // The unit under this whole task is Scroll::FreeSpace(): a profile that is in the file but
        // that the lookup cannot reach is as good as missing. One probe per key, through the same
        // public door the template uses.
        $m = $this->manifest();

        foreach ($this->expectedConfigKeys() as $key) {
            [$order, $variant, $rank] = explode('/', $key);
            $found = Scroll::FreeSpace(['order' => $order, 'variant' => $variant, 'rank' => (int) $rank, 'recipe' => []], $m);
            $this->assertNotNull($found, "FreeSpace() finds nothing for $key");
            $this->assertCount($m['bands'], $found['L'], $key);
        }

        $found = Scroll::FreeSpace(
            ['order' => 'custom', 'variant' => '', 'rank' => 5, 'recipe' => ['ground' => 'parchment', 'border' => 'knot', 'rankSet' => 'zodiac']],
            $m
        );
        $this->assertNotNull($found, 'FreeSpace() finds nothing for a composed custom scroll');
        $this->assertCount($m['bands'], $found['R']);
    }
}
